const modules=[{"title":"Революция 1905–1907 гг.","date":"1905–1907","intro":"Первая российская революция возникла из сочетания аграрного, рабочего, национального и политического вопросов; военные неудачи обострили кризис. Главный результат — появление представительных законодательных институтов при сохранении монархии.","parts":[["Причины","Малоземелье и сохранение помещичьего землевладения; тяжёлые условия труда; отсутствие широких политических прав; национальные противоречия; поражения в Русско-японской войне."],["Характер и задачи","Буржуазно-демократическая по задачам: ограничение самодержавия, гражданские свободы, решение аграрного и рабочего вопросов. Участники — рабочие, крестьяне, часть интеллигенции, армии и флота."],["Итоги","Учреждение законодательной Думы, политические свободы, легализация партий и профсоюзов, отмена выкупных платежей с 1907 г. Монархия и помещичье землевладение сохранились; новый избирательный закон ограничил представительство."]],"headers":["Этап","События","Результат"],"rows":[["Январь – сентябрь 1905","Кровавое воскресенье, Иваново-Вознесенский совет, «Потёмкин», проект Булыгинской думы","Расширение революции"],["Октябрь – декабрь 1905","Всеобщая стачка, Манифест 17 октября, декабрьское восстание","Уступки и последующее подавление выступлений"],["1906 – 3 июня 1907","I и II Думы, аграрные выступления, новый избирательный закон","Спад революции; третьеиюньская система"]],"topics":[6,7,8,9,10,11,12,15,16,17],"scans":[12,13,14,15,18],"q":"Укажите три причины революции и два изменения политического строя в результате революции.","a":"Например: аграрное малоземелье, рабочий вопрос, политическое бесправие. Изменения: законодательная Дума и закрепление гражданских свобод."},{"title":"Партии и четыре Государственные думы","date":"1903–1917","intro":"Многопартийность и парламентские институты возникли в условиях революции. Политические силы различались по отношению к монархии, земле и способам преобразований.","parts":[["Государственное устройство","После 1906 г. закон требовал одобрения Государственной думы, Государственного совета и императора. Император назначал министров, мог распускать Думу и издавать чрезвычайные указы в установленных законом пределах."],["Почему менялся состав Дум","I и II Думы вступали в конфликт с правительством; избирательный закон 3 июня 1907 г. усилил представительство состоятельных групп."],["Аграрный вопрос","Эсеры — социализация земли; кадеты — частичное принудительное отчуждение за вознаграждение; октябристы — преимущественно сохранение частной собственности и постепенные меры."]],"headers":["Дума","Председатели","Основные силы","Итог"],"rows":[["I (1906)","С. А. Муромцев","Кадеты, трудовики","Роспуск"],["II (1907)","Ф. А. Головин","Трудовики, левые, кадеты","Роспуск и новый закон"],["III (1907–1912)","Н. А. Хомяков, А. И. Гучков, М. В. Родзянко","Октябристы, правые","Полный срок"],["IV (1912–1917)","М. В. Родзянко","Правые, октябристы, либералы","Прогрессивный блок, Временный комитет"]],"topics":[3,4,5,13,14,15,16,17,18,19,22],"scans":[3,4,5,6,7,8,9,10,16,17,20],"q":"Какая Дума проработала полный срок и почему её состав отличался от предыдущих?","a":"III Дума; выборы проходили по новому закону 3 июня 1907 г."},{"title":"Русско-японская война","date":"1904–1905","intro":"Соперничество России и Японии за влияние в Корее и Маньчжурии привело к войне. Россия потерпела ряд поражений и заключила Портсмутский мир. Война усугубила внутренний кризис империи.","parts":[["Причины и цели","Соперничество за влияние в Корее и Маньчжурии. Россия арендовала Ляодунский полуостров с Порт-Артуром и строила КВЖД; Япония стремилась закрепить господство в Корее и усилиться в Китае. Англо-японский союз 1902 г. улучшил международное положение Японии."],["Ход войны","1904: бой у Чемульпо («Варяг» и «Кореец»), гибель С. О. Макарова, оборона Порт-Артура, сражения при Ляояне и на реке Шахэ. 1905: поражения при Мукдене и в Цусимском сражении. 23 августа (5 сентября) заключён Портсмутский мир."],["Итоги и последствия","Россия признала преобладающие интересы Японии в Корее, уступила аренду Ляодунского полуострова, южную часть Сахалина и права на южный участок железной дороги. Контрибуции не было. Неудачи войны усилили недовольство самодержавием. Причины поражения: удалённость театра военных действий, ограниченная пропускная способность путей сообщения, ошибки командования и недостаточная подготовка."]],"headers":["Событие","Дата (старый стиль)","Значение"],"rows":[["Бой у Чемульпо","27 января 1904","Начало войны; «Варяг» и «Кореец»"],["Гибель С. О. Макарова","31 марта 1904","Потеря командующего флотом"],["Ляоян","август 1904","Отступление русских войск"],["Сдача Порт-Артура","20 декабря 1904","Потеря военно-морской базы"],["Мукден","февраль 1905","Поражение сухопутной армии"],["Цусима","14–15 мая 1905","Поражение русской эскадры"],["Портсмутский мир","23 августа 1905","Территориальные и политические уступки Японии"]],"topics":[25,6,26],"scans":[11],"q":"Назовите две причины поражения России и два условия Портсмутского мира.","a":"Например: удалённость театра военных действий и недостатки снабжения; уступка Южного Сахалина и арендных прав на Порт-Артур."},{"title":"Экономика: реформы Витте и Столыпина","date":"1890-е – 1917","intro":"Модернизация промышленности сочеталась с сохранением аграрных противоречий. Витте стремился ускорить промышленный рост, Столыпин — преобразовать крестьянское землевладение.","parts":[["С. Ю. Витте: цели и меры","Ускоренная индустриализация, протекционизм, иностранные инвестиции, строительство железных дорог (Транссиб), государственная винная монополия (с 1894 г.), денежная реформа 1897 г. с золотым обеспечением рубля."],["Итоги курса Витте","Промышленный подъём 1890-х гг., укрепление денежной системы и рост железнодорожной сети; одновременно возросли зависимость от иностранных капиталов и нагрузка на общество."],["П. А. Столыпин: цели, меры, итоги","Малоземелье, аграрное перенаселение, крестьянские выступления и низкая эффективность части хозяйств. Столыпин стремился создать слой самостоятельных крестьян-собственников, повысить производительность и стабилизировать деревню. Указ 9 ноября 1906 г. разрешал закреплять общинные наделы в личную собственность. Закон 14 июня 1910 г. закрепил преобразования; закон 29 мая 1911 г. регулировал землеустройство. Поощрялись хутора и отруба, покупки земли при поддержке Крестьянского банка, переселение за Урал. Часть крестьян стала индивидуальными собственниками, расширялись товарное производство и освоение новых земель. Однако многие остались в общинах, помещичье землевладение сохранялось, переселенцы сталкивались с трудностями. Война прервала реформу. Отмена выкупных платежей была объявлена в 1905 г. и полностью осуществлена с 1907 г.; это не указ Столыпина."]],"headers":["Критерий","Витте","Столыпин"],"rows":[["Основная сфера","Промышленность и финансы","Сельское хозяйство"],["Ключевые даты","1892–1903; 1897","1906–1911; реформа до войны"],["Механизм","Государственные заказы, тарифы, золотой рубль","Частное землевладение, банк, переселение"],["Ограничение","Не решён аграрный вопрос","Не устранены малоземелье и социальные конфликты"]],"topics":[30,31,32,33],"scans":[1,2,19,27],"q":"Назовите два различия между курсами Витте и Столыпина и одну общую цель.","a":"Сфера и инструменты реформ различались: промышленность и денежная реформа у Витте, земельная собственность и переселение у Столыпина. Общая цель — модернизация экономики России."},{"title":"Россия в Первой мировой войне","date":"1914–1917","intro":"Россия воевала в составе Антанты. Военные успехи и неудачи сочетались с нарастающими трудностями в тылу, что усилило кризис монархии.","parts":[["Причины и повод","Империалистическое соперничество, конкуренция держав за рынки и колонии, гонка вооружений, противоречия на Балканах. Поводом стало убийство наследника австро-венгерского престола в Сараеве 28 июня 1914 г. по новому стилю."],["Цели России","Поддержка союзников, защита интересов на Балканах и укрепление позиций в районе черноморских проливов. Германия объявила войну России 19 июля (1 августа) 1914 г."],["Последствия","Территориальные потери, огромные военные расходы, инфляция, продовольственные и транспортные трудности, конфликт императора с Думой. Февральская революция свергла монархию, но Россия продолжила войну при Временном правительстве. Брестский мир подписан уже после Октябрьской революции, 3 марта 1918 г."]],"headers":["Год","Фронт","Тыл"],"rows":[["1914","Восточная Пруссия — поражение; Галиция — успех; Кавказский фронт","Патриотический подъём, мобилизация"],["1915","Горлицкий прорыв, Великое отступление","Снарядный голод, Прогрессивный блок, ВПК"],["1916","Брусиловский прорыв; Эрзерум и Трапезунд","Инфляция, перебои снабжения, кризис верхов"],["Начало 1917","Война продолжается","Февральская революция; отречение"]],"topics":[26,27,28,29,21,22,23,24,32],"scans":[21,22,23],"q":"Объясните две причинно-следственные связи между войной и падением монархии.","a":"Например: военные расходы и транспортные затруднения усилили продовольственный кризис и протесты; поражения и частая смена министров подорвали доверие к власти и усилили оппозицию в Думе."},{"title":"Культура Серебряного века","date":"1890-е – 1917","intro":"Период культурного расцвета: реализм сосуществовал с модернизмом, развивались наука, образование, театральное и изобразительное искусство.","parts":[["Литература","Символизм, акмеизм, футуризм; сохранялся реализм (Чехов, Бунин, Куприн)."],["Искусство и архитектура","«Мир искусства», русский авангард, модерн; меценаты Щукин, Морозов и Тенишева поддерживали художников и культурные институции."],["Наука и театр","Павлов, Мечников, Циолковский; МХТ основан в 1898 г. Станиславским и Немировичем-Данченко; Дягилев организовал «Русские сезоны»."]],"headers":["Направление","Деятели","Пример"],"rows":[["Символизм","А. Блок, В. Брюсов","«Незнакомка»"],["Акмеизм","А. Ахматова, Н. Гумилёв","«Вечер»"],["Футуризм","В. Маяковский, В. Хлебников","«Пощёчина общественному вкусу»"],["Модерн","Ф. Шехтель","Ярославский вокзал"],["Супрематизм","К. Малевич","«Чёрный квадрат»"],["Балет","С. Дягилев, М. Фокин, И. Стравинский","«Жар-птица»"]],"topics":[34,35,36,37,38],"scans":[24,25,26],"q":"Соотнесите: Ахматова, Малевич, Шехтель — акмеизм, супрематизм, модерн.","a":"Ахматова — акмеизм; Малевич — супрематизм; Шехтель — модерн."}];
const scanNames=["Формы монополистических объединений","Особенности экономики","Классификация политических партий","Социалистические партии","РСДРП","Большевики и меньшевики","Партия эсеров","Анархистские группы","Либеральные партии","Консервативные партии","Русско-японская война","Революция 1905–1907 гг.: причины и характер","Первый этап революции","Второй этап революции","Третий этап революции","Третьеиюньская система","Государственное устройство после 1905 г.","Итоги революции","Аграрная реформа","Сравнительная таблица Государственных дум","Причины Первой мировой войны","Ход войны","Россия в Первой мировой войне","Русская культура","Развитие науки и культуры","Литература и искусство","Формы монополий"];
